import org.jsoup.nodes.Document;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.Arrays;

public class TextNodeTest {

    @Test
    public void newNodeText_ReturnsCorrectTextNode() {
        Document doc = new Document();
        TextNode node = doc.newTextNode("Hello World");
        assertNotNull(node);
        assertEquals("text", node.nodeName());
        assertEquals("Hello World", node.text());
        assertTrue(!node.isBlank());
    }

    @Test
    public void splitTextZeroOffset_ReturnsCorrectTextNodes() {
        String text = "Hello World";
        Document doc = new Document();
        TextNode node = doc.newTextNode(text);
        TextNode[] result = node.splitText(0);
        assertEquals(1, result.length);
        assertTrue(result[0].text().equals(text));
    }

    @Test
    public void splitTextNonZeroOffset_ReturnsCorrectTextNodes() {
        String text = "Hello World";
        Document doc = new Document();
        TextNode node = doc.newTextNode(text);
        int offset = 6;
        TextNode[] result = node.splitText(offset);
        assertEquals(2, result.length);
        assertTrue(result[0].text().equals("Hello "));
        assertTrue(result[1].text().equals("World"));
    }

    @Test
    public void getWholeText_ReturnsCorrectString() {
        String text = "Hello World";
        Document doc = new Document();
        TextNode node = doc.newTextNode(text);
        assertEquals(text, node.getWholeText());
    }

    @Test
    public void isBlank_ReturnsCorrectBoolean() {
        String text = "";
        Document doc = new Document();
        TextNode node = doc.newTextNode(text);
        assertTrue(node.isBlank());

        text = "   ";
        node = doc.newTextNode(text);
        assertTrue(node.isBlank());
    }

    @Test
    public void clone_RetrunsCorrectTextNode() {
        String text = "Hello World";
        Document doc = new Document();
        TextNode node = doc.newTextNode(text);
        TextNode cloned = node.clone();
        assertNotNull(cloned);
        assertEquals(node.nodeName(), cloned.nodeName());
        assertEquals(node.text(), cloned.text());
    }

    @Test
    public void outerHtmlHead_ThrowsIOException() {
        Appendable accum = Mockito.mock(Appendable.class);
        Document.OutputSettings out = new Document.OutputSettings();
        TextNode node = new TextNode("Hello World");
        try {
            node.outerHtmlHead(accum, 0, out);
            fail("Expected IOException to be thrown.");
        } catch (IOException e) {}
    }

    @Test
    public void outerHtmlTail_ThrowsIOException() {
        Appendable accum = Mockito.mock(Appendable.class);
        Document.OutputSettings out = new Document.OutputSettings();
        TextNode node = new TextNode("");
        try {
            node.outerHtmlTail(accum, 0, out);
            fail("Expected IOException to be thrown.");
        } catch (IOException e) {}
    }

    @Test
    public void normaliseWhitespace_ReturnsCorrectString() {
        String text = "   Hello World";
        assertTrue(TextNode.normaliseWhitespace(text).equals("Hello World"));
    }

    @Test
    public void stripLeadingWhitespace_ReturnsCorrectString() {
        String text = "   Hello World";
        assertEquals("Hello World", TextNode.stripLeadingWhitespace(text));
    }

    @Test
    public void lastCharIsWhitespace_ReturnsCorrectBoolean() {
        StringBuilder sb = new StringBuilder();
        assertTrue(TextNode.lastCharIsWhitespace(sb));
        assertFalse(lastCharIsWhitespace(new StringBuilder()));
    }
}
